CREATE TABLE IF NOT EXISTS users(id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(180) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,role VARCHAR(20) DEFAULT 'tourist' CHECK(role IN('tourist','guide','business','admin')),is_active BOOLEAN DEFAULT TRUE,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS tourist_profiles(id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,user_id INTEGER UNIQUE REFERENCES users(id) ON DELETE CASCADE,phone VARCHAR(30),bio TEXT,preferences JSONB);
CREATE TABLE IF NOT EXISTS guide_profiles(id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,user_id INTEGER UNIQUE REFERENCES users(id) ON DELETE CASCADE,bio TEXT,city VARCHAR(120),languages JSONB,experience_years INT DEFAULT 0,rating NUMERIC(3,2) DEFAULT 0,verified BOOLEAN DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS business_profiles(id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,user_id INTEGER UNIQUE REFERENCES users(id) ON DELETE CASCADE,business_name VARCHAR(180) NOT NULL,description TEXT,city VARCHAR(120),phone VARCHAR(30),website VARCHAR(255),rating NUMERIC(3,2) DEFAULT 0,verified BOOLEAN DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS places(id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,title VARCHAR(180) NOT NULL,description TEXT,category VARCHAR(80),city VARCHAR(120),state VARCHAR(120),latitude NUMERIC(10,7),longitude NUMERIC(10,7),status VARCHAR(20) DEFAULT 'draft',created_by INTEGER REFERENCES users(id) ON DELETE SET NULL,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS discoveries(id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,title VARCHAR(180),description TEXT,category VARCHAR(80),latitude NUMERIC(10,7) NOT NULL,longitude NUMERIC(10,7) NOT NULL,status VARCHAR(20) DEFAULT 'pending',reviewed_by INTEGER REFERENCES users(id) ON DELETE SET NULL,reviewed_at TIMESTAMPTZ,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS discovery_images(id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,discovery_id INTEGER REFERENCES discoveries(id) ON DELETE CASCADE,image_url VARCHAR(500) NOT NULL,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS discovery_verifications(id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,discovery_id INTEGER REFERENCES discoveries(id) ON DELETE CASCADE,authority_id INTEGER REFERENCES users(id) ON DELETE CASCADE,status VARCHAR(20),notes TEXT,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS trips(id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,destination VARCHAR(180) NOT NULL,start_date DATE,end_date DATE,budget NUMERIC(12,2),interests JSONB,status VARCHAR(20) DEFAULT 'draft',travellers INTEGER DEFAULT 1 CHECK(travellers > 0),origin VARCHAR(180),created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS trip_days(id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,trip_id INTEGER REFERENCES trips(id) ON DELETE CASCADE,day_number INT NOT NULL,title VARCHAR(180),trip_date DATE,completed BOOLEAN DEFAULT FALSE,day_budget NUMERIC(12,2) DEFAULT 0,created_at TIMESTAMPTZ DEFAULT NOW(),UNIQUE(trip_id,day_number));
CREATE TABLE IF NOT EXISTS trip_activities(id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,trip_day_id INTEGER REFERENCES trip_days(id) ON DELETE CASCADE,time_label VARCHAR(20),activity_type VARCHAR(40) DEFAULT 'Place',title VARCHAR(180) NOT NULL,description TEXT,planned_cost NUMERIC(12,2) DEFAULT 0,actual_cost NUMERIC(12,2),completed BOOLEAN DEFAULT FALSE,sort_order INTEGER DEFAULT 0,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS trip_expenses(id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,trip_id INTEGER REFERENCES trips(id) ON DELETE CASCADE,activity_id INTEGER REFERENCES trip_activities(id) ON DELETE SET NULL,category VARCHAR(80),amount NUMERIC(12,2) NOT NULL CHECK(amount >= 0),note TEXT,spent_at TIMESTAMPTZ DEFAULT NOW(),created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS bookings(id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,tourist_id INTEGER REFERENCES users(id),provider_id INTEGER REFERENCES users(id),provider_type VARCHAR(20),trip_id INTEGER REFERENCES trips(id),booking_date DATE,status VARCHAR(20) DEFAULT 'pending',notes TEXT,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS reviews(id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,user_id INTEGER REFERENCES users(id),target_user_id INTEGER REFERENCES users(id),place_id INTEGER REFERENCES places(id),rating SMALLINT CHECK(rating BETWEEN 1 AND 5),comment TEXT,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_trips_user ON trips(user_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_trip_days_trip ON trip_days(trip_id,day_number);
CREATE INDEX IF NOT EXISTS idx_trip_activities_day ON trip_activities(trip_day_id,sort_order);
CREATE INDEX IF NOT EXISTS idx_trip_expenses_trip ON trip_expenses(trip_id,spent_at DESC);
INSERT INTO places(title,description,category,city,state,latitude,longitude,status) SELECT 'Araku Hidden Valley','Community tourism prototype','Nature & Adventure','Araku Valley','Andhra Pradesh',18.3273,82.8775,'published' WHERE NOT EXISTS(SELECT 1 FROM places WHERE title='Araku Hidden Valley');